"""Summarize recorded Phase 73 measurements; never change an execution backend."""
import json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'analysis/undercover'
def generate():
 baseline=json.loads((D/'browser-x86-cost-baseline-phase73.json').read_text());final=json.loads((D/'browser-x86-optimization-phase73.json').read_text());reg=json.loads((D/'browser-x86-optimization-phase73-regression.json').read_text())
 best=next(r for r in final['experiments'] if r['name']=='B_persistent_checked');a=next(r for r in final['experiments'] if r['name']=='A_combined_full')
 categories={}
 for name in baseline['profiles'][0]['costs']['categories']:
  rows=[p['costs']['categories'].get(name,{'calls':0,'inclusiveMs':0,'exclusiveMs':0}) for p in baseline['profiles']]
  categories[name]={k:statistics.median(r[k] for r in rows) for k in ['calls','inclusiveMs','exclusiveMs']}
 counters=final['profiles'][0]['costs'].get('counters',{})
 report={'phase':73,'decision':'NO_GO_CLOSE_APPROACH' if best['fair']['ratio']>5 and a['ratio']>5 else 'REVIEW_GATE_RESULT','thresholdRatio':5,'baselineBeforeOptimization':baseline['baseline'],'baselineProfileSamples':baseline['profiles'],'baselineProfileMedianCategories':categories,'profileOverheadRatio':statistics.median(p['durationMs'] for p in baseline['profiles'])/baseline['baseline']['costAdapterUnprofiled']['median'],'baselineCopyOverheadRatio':baseline['baseline']['costAdapterUnprofiled']['median']/baseline['baseline']['originalAdapter']['median'],'correctedFactoryAndExternalCosts':final['externalCosts'],'setupPermissionFailuresPerBaselineProfile':counters.get('permissionCheckFailures'),'modeA':a,'modeB':best,'concurrentRegressionModeBRatio':next(r for r in reg['experiments'] if r['name']=='B_persistent_checked')['fair']['ratio'],'resetResults':final['resetTests'],'resetFailureFixtures':final['resetProbes'],'optimizedBudgetCases':final['optimizedBudgets'],'browserVersion':final['browserVersion'],'engineVersion':final['engineVersion'],'canonicalLinearMemoryBytes':final['memoryBytes'],'engineLinearMemoryBytes':final['engineMemoryBytes'],'workerRoundTripMs':final['workerRoundTripMs'],'workerBootPingMs':final['workerBootPingMs'],'workerWarmPingMs':final['workerWarmPingMs'],'workerBundleBytes':final['workerBundleBytes'],'engineDownloadBytes':915283,'referenceWasmBytes':14981,'originalControl':final['reference'],'units':'milliseconds; inclusive timings overlap; exclusive category medians are not additive medians of one run','productionBackendChanged':False,'originalStartupAdvanced':False,'newOriginalFunctions':0,'furtherPerformanceTuningRecommended':False,'sourceBuildReproducibility':'NOT_ESTABLISHED','redistribution':'GPL obligations remain unresolved for deployment; engine remains external test-only'}
 if report['decision']!='NO_GO_CLOSE_APPROACH':raise ValueError('Unexpected adoption result requires review, not automatic promotion')
 (D/'browser-x86-cost-breakdown-phase73.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
 lines=['# Phase 73 — Final browser x86 adoption decision','','**NO-GO. Close this adapter approach for adoption and retain Unicorn.js as a test-only differential oracle.**','','The initial slowdown was primarily removable adapter overhead, not evidence that every browser x86 engine is inherently incapable. The bounded optimizations removed most of that overhead, but the remaining checked path still fails the unchanged <=5x gate. No further tuning or new engine candidate is recommended in this phase.','','| Checked mode | x86 median ms | Comparable Wasm median ms | Ratio | Gate |','|---|---:|---:|---:|---|',f"| A: full diagnostics, combined optimizations | {a['warm']['median']:.3f} | {a['wasm']['median']:.3f} | {a['ratio']:.2f}x | FAIL |",f"| B: checked persistent/batched path, grouped means | {best['fair']['x86']['median']:.3f} | {best['fair']['wasm']['median']:.3f} | {best['fair']['ratio']:.2f}x | FAIL |",'', 'The Mode B Wasm callbacks for optional snapshots/reads are removed on the existing observer object; its mandatory journals and safety behavior remain. X86 similarly omits only optional snapshots and verbose read storage. Both keep permission checks, source authentication, instruction admission, flags/FS, budgets, write ordering and unsupported-target rejection. Reduced instrumentation does not claim instruction-snapshot equivalence; complete twelve-category correctness is independently revalidated in Mode A and every persistent recovery case.','',f"A separate concurrent regression campaign measured Mode B at {report['concurrentRegressionModeBRatio']:.2f}x. Neither campaign approaches 5x. Cold is the first engine/session run after the module factory is initialized; it is not a cold-machine or network-load claim. Seven groups of ten paired runs improve timer resolution in Mode B; all raw values, variance and cold/warm results are in browser-x86-optimization-phase73.json.",'','## Measured baseline and changes','','Baseline before optimization: original adapter median %.3f ms; matching unprofiled cost adapter %.3f ms. Fine-grained profiling median %.3f ms (%.2fx instrumentation overhead). Independent wall time and inclusive/exclusive nested counters are retained; inclusive totals must not be summed.'%(baseline['baseline']['originalAdapter']['median'],baseline['baseline']['costAdapterUnprofiled']['median'],statistics.median(p['durationMs'] for p in baseline['profiles']),report['profileOverheadRatio']),'','The five timer yields consumed a median %.3f ms. Byte-wise page filling caused %d permission checks per profiled baseline run; %d denied setup-padding probes occur at the last partial data page, not in the 68 successful CPU reads. Source and permission checks were retained. Whole-page bulk copying alone did not remove the expensive partial-page fallback.'%(categories['cooperativeYields']['exclusiveMs'],categories['guestPermissionChecks']['calls'],counters.get('permissionCheckFailures',0)),'','| Experiment | Cold ms | Warm median ms | Warm min / max ms | Label |','|---|---:|---:|---:|---|']
 for r in final['experiments']:lines.append(f"| {r['name']} | {r['coldMs']:.3f} | {r['warm']['median']:.3f} | {r['warm']['min']:.3f} / {r['warm']['max']:.3f} | {r['mode']} |")
 lines+=['','Mode C changes one setting at a time: yield interval, checked bulk page copy, snapshots, persistence, or batch size. Combined A and B cases are explicitly cumulative. Baseline uses single-step execution and five timer yields. Combined cases use batches of 16 and no between-batch timer yields in a dedicated bounded worker; per-instruction code hooks and all memory hooks remain active, with a 1,000 ms run budget and 60-second outer worker termination watchdog. This does not remove main-thread watchdog protection.','', 'Persistent reuse saves the pristine CPU context after synthetic segment initialization, restores registers/segments/flags, clears per-run frames/hooks/traps/metadata/budgets, and copies every attempted dirty range from the reset canonical memory. Host root return-slot state is synchronized explicitly. Every data read still compares with canonical checked memory. The engine never becomes the unchecked authority.','',f"The final warm persistent profile maps {best['synchronization']['pagesMappedThisRun']} new pages and restores {best['synchronization']['restoredRanges']} ranges / {best['synchronization']['restoredBytes']} bytes. Complete mapped guest-memory comparison, including stack and FS storage, passes. Recovery passes after provider, budget, synthetic UD2 and a stronger host permission-policy failure on the original first PUSH. This validates this control fixture, not arbitrary Windows exceptions or all malformed accesses.",'','Batched code hooks finalize the previous instruction, check CALL/RET and definedness, and admit the next original instruction before it executes. An unmapped effective target is rejected on the engine fetch exception; a mapped unadmitted target is rejected before its instruction hook admits execution. Every observed code-hook sequence remains the same 173 tags. Raw engine EIP 0x008AAC6A and normalized original-callsite stop 0x0087B5B3 are retained.','', 'Remaining warm cost is concentrated in the checked instruction engine/host boundary, admission/source comparisons and callbacks. Batching reduces 173 engine-start calls to 11 but retains 173 admission hooks, 68 checked reads and 82 ordered writes. Eliminating all timer yields and repeated mapping already fails the gate. Reaching 5x from the measured Mode B median would require another %.1f%% reduction; the measurements do not justify predicting that from another small adapter change.'%(100*(1-5/best['fair']['ratio'])),'','This is a practical rejection of the tested checked adapter, not a theoretical lower bound for CPU emulation. Profiling itself changes cost; profiled counters are explanatory and do not replace unprofiled gate timings. No FPS extrapolation, RSS claim, unmeasured native comparison or permanent production integration is made.','', '## Deployment and next work','','Production translated Wasm, full-game disabled state, manifest, source payload and media remain unchanged. Source-build reproducibility and GPL corresponding-source/distribution obligations remain independent deployment gates even if performance had passed. No engine binary or commercial asset is committed.','', 'Return Phase 74 to the actual original-startup dependency graph. Pick one evidence-supported ordinary edge or externally documented contract tied to a real blocker. Closed legacy binding searches may reopen only with new independent writer/loader/binding evidence; do not repeat positional-table inference, fabricate provider state or fill unavailable code. No more CPU tuning, new backend candidate, helper-count expansion, SIMD, graphics or gameplay claim is warranted by Phase 73.']
 (D/'browser-x86-decision-phase73.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 return report
if __name__=='__main__':generate()
